const input = $input.first().json;
const headers = Object.fromEntries(Object.entries(input.headers ?? {}).map(([key, value]) => [key.toLowerCase(), String(value)]));
const event = headers['x-taxtronik-event'] ?? '';
const timestamp = headers['x-taxtronik-timestamp'] ?? '';
const nonce = headers['x-taxtronik-nonce'] ?? '';
const signature = headers['x-taxtronik-signature'] ?? '';
if (event !== 'request.opened') throw new Error('Unerwarteter TaxTronik-Event');
if (!/^\d{13}$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 300000) throw new Error('TaxTronik-Timestamp ungueltig');
if (!/^[A-Za-z0-9._:-]{16,200}$/.test(nonce)) throw new Error('TaxTronik-Nonce ungueltig');
const expected = 'sha256=' + String(input.expectedSignature ?? '');
if (!/^sha256=[a-f0-9]{64}$/i.test(signature) || signature.length !== expected.length) throw new Error('TaxTronik-Signatur ungueltig');
let mismatch = 0;
for (let i = 0; i < signature.length; i++) mismatch |= signature.charCodeAt(i) ^ expected.charCodeAt(i);
if (mismatch !== 0) throw new Error('TaxTronik-Signatur ungueltig');
let body;
try { body = typeof input.body === 'string' ? JSON.parse(input.body) : input.body; } catch { throw new Error('TaxTronik-Body ist kein JSON'); }
if (!body || body.event !== 'request.opened') throw new Error('Event in Body und Header stimmen nicht ueberein');
const deliveryId = String(body.deliveryId ?? '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(deliveryId)) throw new Error('TaxTronik-Delivery-ID ungueltig');
if (headers['x-taxtronik-delivery-id'] !== deliveryId) throw new Error('Delivery-ID in Body und Header stimmen nicht ueberein');
return [{ json: { ...input, headers, body } }];
